def add(a,b): return tuple(x+y for x,y in zip(a,b))
def neg(a): return tuple(-x for x in a)
def sub(a,b): return add(a,neg(b))
def unit(n,i): return tuple(_sage_const_1  if j==i else _sage_const_0  for j in range(n))
def root_window(n):
    e=[unit(n,i) for i in range(n)]; zero=(_sage_const_0 ,)*n
    return sorted({zero}|{sub(x,y) for x in e for y in e})
def fisher_window(n):
    e=[unit(n,i) for i in range(n)]
    charge={add(add(e[a],e[b]),neg(e[c])) for a in range(n) for b in range(a,n) for c in range(n)}
    return sorted({sub(x,e[-_sage_const_1 ]) for x in charge})
def shift(S,q,mod=None):
    index={x:i for i,x in enumerate(S)}; entries={}
    for j,x in enumerate(S):
        y=(x+q)%mod if mod else add(x,q)
        if y in index: entries[(index[y],j)]=_sage_const_1 
    return matrix(QQ,len(S),len(S),entries,sparse=True)
def comm(A,B): return A*B-B*A

def signature_integer_spectrum(A):
    assert A==A.transpose()
    pol=A.charpoly(); factors=pol.factor(); pos=negc=zero=_sage_const_0 
    for f,k in factors:
        assert f.degree()==_sage_const_1 , (f,k)
        ev=-f[_sage_const_0 ]/f[_sage_const_1 ]
        if ev>_sage_const_0 : pos+=k
        elif ev<_sage_const_0 : negc+=k
        else: zero+=k
    return (int(pos),int(negc),int(zero))

